    {
        Span<int> instruction = [(int)Op.OpSource, (int)SourceLanguage, ..Version.AsDisposableLiteralValue().Words, ..(File is null ? (Span<int>)[] : [File.Value]), ..(Source is null ? (Span<int>)[] : Source.AsDisposableLiteralValue().Words)];
