        set
        {
            field = value;
            if (!InstructionMemory.IsEmpty)
                UpdateInstructionMemory();
        }
    }

    public static implicit operator int (GLSLLog2 inst) => inst.ResultId;
    public static implicit operator SpirvValue(GLSLLog2 inst) => inst.ToValue();
    public SpirvValue ToValue() => new(ResultId, ResultType);
    public GLSLLog2(int resultType, int resultId, int set, int x)
    {
        ResultType = resultType;
        ResultId = resultId;
        Set = set;
        X = x;
        UpdateInstructionMemory();
        opData = ref Unsafe.NullRef<OpData>();
    }

    public void Attach(OpDataIndex index)
    {
        attachedBuffer = index.Buffer;
        attachedIndex = index.Index;
        attachedVersion = index.Buffer.StructureVersion;
    }

    [Conditional("DEBUG")]
    private readonly void CheckAttached()
    {
        if (attachedBuffer!.StructureVersion != attachedVersion)
            throw new InvalidOperationException("This instruction was taken from a SpirvBuffer whose instructions moved since then: take it from the buffer again.");
    }

    public void UpdateInstructionMemory()
    {
        Span<int> instruction = [(int)Op.OpExtInst, ResultType, ResultId, Set, (int)GLSLOp.GLSLLog2, X];
        instruction[0] |= instruction.Length << 16;
        if (attachedBuffer is not null)
        {
            CheckAttached();
            attachedBuffer.SetWords(attachedIndex, instruction);
            return;
        }

        if (instruction.Length == InstructionMemory.Length)
            instruction.CopyTo(InstructionMemory.Span);
        else
            InstructionMemory = instruction.ToArray();
    }

    private void InitializeProperties(OpData data)
    {
        foreach (var o in data)
        {
            switch (o.Name)
            {
                case "resultType":
                    ResultType = o.ToLiteral<int>();
                    break;
                case "resultId":
                    ResultId = o.ToLiteral<int>();
                    break;
                case "set":
                    Set = o.ToLiteral<int>();
                    break;
                case "x":
                    X = o.ToLiteral<int>();
                    break;
                // We ignore unrecognized operands
                default:
                    break;
            }
        }
    }

    public static implicit operator GLSLLog2(OpDataIndex odi) => new(odi);
}

